// Autogenerated embedded HTML viewer for Mnesia Knowledge Graph
export function getViewerHtml(supabaseUrl = "", supabaseKey = ""): string {
  const injectedScript = `
    <script>
      window.__DEFAULT_SUPABASE_URL__ = "${supabaseUrl}";
      window.__DEFAULT_SUPABASE_KEY__ = "${supabaseKey}";
    </script>
  `;
  const rawHtml = "<!DOCTYPE html>\n<html lang=\"en\" class=\"dark\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Mnesia — Knowledge Graph Visualizer & Explorer</title>\n  <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>🕸️</text></svg>\">\n  \n  <!-- Tailwind CSS CDN -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              50: '#ecfdf5',\n              400: '#34d399',\n              500: '#10b981',\n              600: '#059669',\n              700: '#047857',\n            },\n            dark: {\n              950: '#090d16',\n              900: '#0f172a',\n              850: '#131d35',\n              800: '#1e293b',\n              700: '#334155',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- Vis Network CDN -->\n  <script src=\"https://unpkg.com/vis-network@9.1.9/standalone/umd/vis-network.min.js\"></script>\n\n  <!-- Lucide Icons CDN -->\n  <script src=\"https://unpkg.com/lucide@latest\"></script>\n\n  <!-- Marked.js Markdown Parser -->\n  <script src=\"https://cdn.jsdelivr.net/npm/marked/marked.min.js\"></script>\n\n  <style>\n    /* Custom scrollbars */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: #0f172a;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #334155;\n      border-radius: 3px;\n    }\n    ::-webkit-scrollbar-thumb:hover {\n      background: #475569;\n    }\n\n    /* Markdown prose styles in inspector */\n    .prose-dark {\n      color: #cbd5e1;\n      font-size: 0.775rem;\n      line-height: 1.45rem;\n      word-break: break-word;\n    }\n    .prose-dark p {\n      margin-bottom: 0.6rem;\n    }\n    .prose-dark p:last-child {\n      margin-bottom: 0;\n    }\n    .prose-dark h1, .prose-dark h2, .prose-dark h3, .prose-dark h4 {\n      color: #f8fafc;\n      font-weight: 700;\n      margin-top: 0.9rem;\n      margin-bottom: 0.35rem;\n    }\n    .prose-dark h1 { font-size: 0.95rem; }\n    .prose-dark h2 { font-size: 0.875rem; border-bottom: 1px solid #334155; padding-bottom: 0.2rem; }\n    .prose-dark h3 { font-size: 0.8rem; color: #38bdf8; }\n    .prose-dark ul, .prose-dark ol {\n      margin-left: 1.25rem;\n      margin-bottom: 0.6rem;\n    }\n    .prose-dark ul { list-style-type: disc; }\n    .prose-dark ol { list-style-type: decimal; }\n    .prose-dark li {\n      margin-bottom: 0.25rem;\n    }\n    .prose-dark code {\n      background-color: #090d16;\n      border: 1px solid #334155;\n      color: #38bdf8;\n      padding: 0.15rem 0.35rem;\n      border-radius: 0.25rem;\n      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n      font-size: 0.725rem;\n    }\n    .prose-dark pre {\n      background-color: #050811;\n      border: 1px solid #1e293b;\n      border-radius: 0.5rem;\n      padding: 0.6rem;\n      margin: 0.5rem 0;\n      overflow-x: auto;\n    }\n    .prose-dark pre code {\n      background: transparent;\n      border: 0;\n      padding: 0;\n      color: #a5f3fc;\n    }\n    .prose-dark blockquote {\n      border-left: 3px solid #10b981;\n      padding-left: 0.6rem;\n      color: #94a3b8;\n      font-style: italic;\n      margin: 0.5rem 0;\n    }\n    .prose-dark a {\n      color: #34d399;\n      text-decoration: underline;\n      text-underline-offset: 2px;\n    }\n    .prose-dark hr {\n      border: 0;\n      border-top: 1px solid #334155;\n      margin: 0.75rem 0;\n    }\n    /* Vis network navigation overrides for sleek dark look */\n    .vis-network div.vis-navigation div.vis-button {\n      background-color: #1e293b !important;\n      border: 1px solid #334155 !important;\n      border-radius: 8px !important;\n      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.4) !important;\n    }\n    .vis-network div.vis-navigation div.vis-button:hover {\n      background-color: #334155 !important;\n    }\n  </style>\n</head>\n<body class=\"bg-dark-950 text-slate-100 h-screen w-screen flex flex-col overflow-hidden font-sans antialiased select-none\">\n\n  <!-- ================= TOP NAVIGATION / HEADER ================= -->\n  <header class=\"h-14 border-b border-slate-800 bg-dark-900/90 backdrop-blur px-4 flex items-center justify-between z-20 shrink-0\">\n    <!-- Left: Brand & Status -->\n    <div class=\"flex items-center gap-3\">\n      <div class=\"flex items-center gap-2\">\n        <div class=\"w-8 h-8 rounded-lg bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400 font-bold text-lg shadow-sm\">\n          🕸️\n        </div>\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span class=\"font-bold tracking-tight text-white text-base\">Mnesia</span>\n            <span class=\"text-xs px-2 py-0.5 rounded-full bg-emerald-950/80 text-emerald-400 border border-emerald-800/60 font-medium\">KG Viewer</span>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"h-5 w-px bg-slate-800 mx-1\"></div>\n\n      <!-- Live Connection Status Badge -->\n      <button id=\"btnConnectionStatus\" onclick=\"openSettingsModal()\" class=\"flex items-center gap-2 px-2.5 py-1 rounded-md bg-dark-800 hover:bg-dark-700 border border-slate-700/80 transition text-xs text-slate-300\">\n        <span id=\"statusIndicator\" class=\"w-2 h-2 rounded-full bg-amber-400 animate-pulse\"></span>\n        <span id=\"statusText\">Demo Dataset</span>\n      </button>\n\n      <!-- Refresh Button -->\n      <button id=\"btnSync\" onclick=\"refreshData()\" title=\"Reload from source\" class=\"p-1.5 rounded-md hover:bg-dark-800 text-slate-400 hover:text-white transition border border-transparent hover:border-slate-700\">\n        <i data-lucide=\"refresh-cw\" class=\"w-4 h-4\"></i>\n      </button>\n    </div>\n\n    <!-- Center: Search Bar & Auto-Focus -->\n    <div class=\"relative w-80 max-w-sm\">\n      <div class=\"relative\">\n        <i data-lucide=\"search\" class=\"w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none\"></i>\n        <input \n          type=\"text\" \n          id=\"searchInput\" \n          placeholder=\"Search entities, types, aliases...\" \n          class=\"w-full pl-9 pr-8 py-1.5 bg-dark-800 border border-slate-700/80 rounded-lg text-xs text-white placeholder-slate-400 focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition\"\n          oninput=\"handleSearch(this.value)\"\n        >\n        <button id=\"btnClearSearch\" onclick=\"clearSearch()\" class=\"hidden absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white text-xs\">\n          ✕\n        </button>\n      </div>\n      <!-- Autocomplete Dropdown -->\n      <div id=\"searchDropdown\" class=\"hidden absolute top-full mt-1.5 left-0 right-0 max-h-60 overflow-y-auto bg-dark-800 border border-slate-700 rounded-lg shadow-xl z-50 py-1\"></div>\n    </div>\n\n    <!-- Right: Stats & Action Tools -->\n    <div class=\"flex items-center gap-2\">\n      <!-- Counters Pill -->\n      <div class=\"hidden md:flex items-center gap-3 px-3 py-1 bg-dark-800/80 border border-slate-800 rounded-md text-xs text-slate-400 font-mono\">\n        <div><span id=\"statEntities\" class=\"text-emerald-400 font-semibold\">0</span> entities</div>\n        <div class=\"w-1 h-1 rounded-full bg-slate-700\"></div>\n        <div><span id=\"statRelations\" class=\"text-sky-400 font-semibold\">0</span> relations</div>\n        <div class=\"w-1 h-1 rounded-full bg-slate-700\"></div>\n        <div><span id=\"statMemories\" class=\"text-purple-400 font-semibold\">0</span> memories</div>\n      </div>\n\n      <!-- Quick Action Buttons -->\n      <div class=\"flex items-center gap-1 border-l border-slate-800 pl-2\">\n        <button onclick=\"fitGraph()\" title=\"Fit View to All Nodes\" class=\"p-1.5 rounded-md hover:bg-dark-800 text-slate-400 hover:text-white transition border border-transparent hover:border-slate-700\">\n          <i data-lucide=\"maximize\" class=\"w-4 h-4\"></i>\n        </button>\n        <button id=\"btnPhysicsToggle\" onclick=\"togglePhysics()\" title=\"Toggle Physics Simulation\" class=\"p-1.5 rounded-md hover:bg-dark-800 text-emerald-400 hover:text-emerald-300 transition border border-transparent hover:border-slate-700\">\n          <i data-lucide=\"activity\" class=\"w-4 h-4\"></i>\n        </button>\n        <button id=\"btnLayoutToggle\" onclick=\"toggleLayoutMode()\" title=\"Toggle Hierarchical / Force Layout\" class=\"p-1.5 rounded-md hover:bg-dark-800 text-slate-400 hover:text-white transition border border-transparent hover:border-slate-700\">\n          <i data-lucide=\"git-fork\" class=\"w-4 h-4\"></i>\n        </button>\n        <button onclick=\"exportPNG()\" title=\"Export PNG Screenshot\" class=\"p-1.5 rounded-md hover:bg-dark-800 text-slate-400 hover:text-white transition border border-transparent hover:border-slate-700\">\n          <i data-lucide=\"camera\" class=\"w-4 h-4\"></i>\n        </button>\n        <button onclick=\"openSettingsModal()\" title=\"Supabase API Settings\" class=\"p-1.5 rounded-md hover:bg-dark-800 text-slate-400 hover:text-white transition border border-transparent hover:border-slate-700\">\n          <i data-lucide=\"settings\" class=\"w-4 h-4\"></i>\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- ================= MAIN WORKSPACE AREA ================= -->\n  <div class=\"relative flex-1 flex overflow-hidden\">\n    \n    <!-- Floating Filter Controls Bar (Left Top) -->\n    <div class=\"absolute top-3 left-3 z-10 flex flex-col gap-2 max-w-sm pointer-events-none\">\n      <!-- Entity Type Filter Chips -->\n      <div class=\"pointer-events-auto bg-dark-900/90 backdrop-blur-md border border-slate-800 rounded-xl p-2.5 shadow-xl\">\n        <div class=\"flex items-center justify-between mb-2\">\n          <span class=\"text-[11px] font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-1.5\">\n            <i data-lucide=\"filter\" class=\"w-3 h-3 text-slate-400\"></i> Entity Types\n          </span>\n          <button onclick=\"resetFilters()\" class=\"text-[10px] text-emerald-400 hover:underline\">Reset</button>\n        </div>\n        <div id=\"typeFilterPills\" class=\"flex flex-wrap gap-1.5 max-h-32 overflow-y-auto pr-1\"></div>\n      </div>\n\n      <!-- Display Options -->\n      <div class=\"pointer-events-auto bg-dark-900/90 backdrop-blur-md border border-slate-800 rounded-xl p-2.5 shadow-xl flex items-center justify-between text-xs\">\n        <label class=\"flex items-center gap-2 cursor-pointer select-none\">\n          <input type=\"checkbox\" id=\"chkShowSuperseded\" onchange=\"toggleSuperseded(this.checked)\" class=\"rounded bg-dark-800 border-slate-700 text-emerald-500 focus:ring-0\">\n          <span class=\"text-slate-300\">Show Superseded Links</span>\n        </label>\n        <span id=\"supersededCountPill\" class=\"text-[10px] font-mono px-1.5 py-0.5 rounded bg-red-950/60 text-red-400 border border-red-900/60\">0</span>\n      </div>\n\n      <!-- Hop Focus Mode Pill -->\n      <div id=\"focusModeBox\" class=\"hidden pointer-events-auto bg-dark-900/90 backdrop-blur-md border border-slate-800 rounded-xl p-2.5 shadow-xl flex items-center justify-between text-xs\">\n        <div class=\"flex items-center gap-1.5 text-slate-300\">\n          <i data-lucide=\"crosshair\" class=\"w-3.5 h-3.5 text-emerald-400\"></i>\n          <span>Neighborhood Focus:</span>\n          <span id=\"focusEntityName\" class=\"font-medium text-white truncate max-w-[100px]\">Node</span>\n        </div>\n        <button onclick=\"clearFocusMode()\" class=\"text-xs text-red-400 hover:text-red-300 font-medium ml-2\">Exit</button>\n      </div>\n    </div>\n\n    <!-- Graph Canvas Container -->\n    <div id=\"graphContainer\" class=\"flex-1 w-full h-full bg-[#080d19]\"></div>\n\n    <!-- Floating Empty / Helper Badge (Bottom Left) -->\n    <div class=\"absolute bottom-3 left-3 z-10 pointer-events-none bg-dark-900/80 backdrop-blur border border-slate-800/80 rounded-lg px-3 py-1.5 text-[11px] text-slate-400 flex items-center gap-3\">\n      <span>🖱️ Click node/edge to inspect</span>\n      <span>•</span>\n      <span>Double click to focus neighborhood</span>\n      <span>•</span>\n      <span>Scroll to zoom</span>\n    </div>\n\n    <!-- ================= RIGHT SLIDE-OVER INSPECTOR DRAWER ================= -->\n    <aside id=\"inspectorDrawer\" class=\"w-96 max-w-full border-l border-slate-800 bg-dark-900/95 backdrop-blur-md flex flex-col z-20 transition-transform duration-300 ease-in-out translate-x-full shadow-2xl\">\n      <!-- Drawer Header -->\n      <div class=\"h-14 border-b border-slate-800 px-4 flex items-center justify-between shrink-0\">\n        <div class=\"flex items-center gap-2 overflow-hidden\">\n          <i id=\"inspectorIcon\" data-lucide=\"circle-dot\" class=\"w-4 h-4 text-emerald-400 shrink-0\"></i>\n          <h2 id=\"inspectorTitle\" class=\"text-sm font-bold text-white truncate\">Inspector</h2>\n        </div>\n        <div class=\"flex items-center gap-1\">\n          <button id=\"btnToggleDrawerWidth\" onclick=\"toggleDrawerWidth()\" title=\"Toggle Wide View (Markdown reading)\" class=\"p-1 rounded-md text-slate-400 hover:text-white hover:bg-dark-800 transition\">\n            <i id=\"iconDrawerWidth\" data-lucide=\"maximize-2\" class=\"w-4 h-4\"></i>\n          </button>\n          <button onclick=\"closeInspector()\" class=\"p-1 rounded-md text-slate-400 hover:text-white hover:bg-dark-800 transition\">\n            <i data-lucide=\"x\" class=\"w-4 h-4\"></i>\n          </button>\n        </div>\n      </div>\n\n      <!-- Drawer Scrollable Content -->\n      <div id=\"inspectorContent\" class=\"flex-1 overflow-y-auto p-4 space-y-5 text-xs text-slate-300\">\n        <!-- Content will be rendered dynamically -->\n      </div>\n    </aside>\n  </div>\n\n  <!-- ================= SETTINGS & SUPABASE CREDENTIALS MODAL ================= -->\n  <div id=\"settingsModal\" class=\"hidden fixed inset-0 z-50 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4\">\n    <div class=\"w-full max-w-md bg-dark-900 border border-slate-800 rounded-2xl shadow-2xl overflow-hidden flex flex-col\">\n      <!-- Modal Header -->\n      <div class=\"px-5 py-4 border-b border-slate-800 flex items-center justify-between\">\n        <div class=\"flex items-center gap-2\">\n          <div class=\"w-7 h-7 rounded-lg bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400\">\n            <i data-lucide=\"database\" class=\"w-4 h-4\"></i>\n          </div>\n          <h3 class=\"font-bold text-white text-sm\">Supabase Connection Settings</h3>\n        </div>\n        <button onclick=\"closeSettingsModal()\" class=\"text-slate-400 hover:text-white\">\n          <i data-lucide=\"x\" class=\"w-4 h-4\"></i>\n        </button>\n      </div>\n\n      <!-- Modal Body -->\n      <div class=\"p-5 space-y-4 text-xs\">\n        <p class=\"text-slate-400 leading-relaxed\">\n          Connect directly to your Supabase PostgreSQL tables (<code class=\"text-emerald-400 font-mono\">public.entities</code>, <code class=\"text-emerald-400 font-mono\">public.relations</code>, <code class=\"text-emerald-400 font-mono\">public.memories</code>).\n        </p>\n\n        <div>\n          <label class=\"block text-slate-300 font-medium mb-1\">Supabase URL</label>\n          <input \n            type=\"url\" \n            id=\"cfgSupabaseUrl\" \n            placeholder=\"https://xyzcompany.supabase.co\" \n            class=\"w-full px-3 py-2 bg-dark-800 border border-slate-700 rounded-lg text-white font-mono placeholder-slate-500 focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500\"\n          >\n        </div>\n\n        <div>\n          <label class=\"block text-slate-300 font-medium mb-1\">Supabase API Key (Anon or Service Role)</label>\n          <input \n            type=\"password\" \n            id=\"cfgSupabaseKey\" \n            placeholder=\"eyJh...\" \n            class=\"w-full px-3 py-2 bg-dark-800 border border-slate-700 rounded-lg text-white font-mono placeholder-slate-500 focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500\"\n          >\n          <span class=\"text-[10px] text-slate-500 mt-1 block\">Saved in browser's local storage only. Never sent to any 3rd party.</span>\n        </div>\n\n        <div id=\"modalStatusAlert\" class=\"hidden p-3 rounded-lg border text-xs\"></div>\n      </div>\n\n      <!-- Modal Footer -->\n      <div class=\"px-5 py-3 border-t border-slate-800 bg-dark-950 flex items-center justify-between\">\n        <button onclick=\"loadDemoDataset()\" class=\"px-3 py-1.5 rounded-lg bg-dark-800 hover:bg-dark-700 text-slate-300 border border-slate-700 transition text-xs flex items-center gap-1.5\">\n          <i data-lucide=\"sparkles\" class=\"w-3.5 h-3.5 text-amber-400\"></i> Load Demo Graph\n        </button>\n        <div class=\"flex items-center gap-2\">\n          <button onclick=\"closeSettingsModal()\" class=\"px-3 py-1.5 rounded-lg hover:bg-dark-800 text-slate-400 hover:text-white transition text-xs\">\n            Cancel\n          </button>\n          <button onclick=\"saveAndConnectSupabase()\" class=\"px-4 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-lg shadow-emerald-900/40 transition text-xs flex items-center gap-1.5\">\n            <i data-lucide=\"check\" class=\"w-3.5 h-3.5\"></i> Connect & Sync\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= JAVASCRIPT APPLICATION LOGIC ================= -->\n  <script>\n    // --- STATE MANAGEMENT ---\n    let network = null;\n    let rawEntities = [];\n    let rawRelations = [];\n    let rawMemories = [];\n    let rawMemoryEntities = [];\n    \n    let isPhysicsActive = true;\n    let isHierarchical = false;\n    let activeTypeFilters = new Set();\n    let showSuperseded = false;\n    let selectedEntityId = null;\n    let focusCenterEntityId = null;\n    let focusHopDepth = 0; // 0 = all nodes\n\n    // Visual Palette by Entity Type\n    const TYPE_STYLES = {\n      concept: { bg: '#8B5CF6', border: '#A78BFA', highlight: '#C4B5FD', badge: 'bg-purple-950/80 text-purple-300 border-purple-800/80' },\n      component: { bg: '#0284C7', border: '#38BDF8', highlight: '#7DD3FC', badge: 'bg-sky-950/80 text-sky-300 border-sky-800/80' },\n      technology: { bg: '#059669', border: '#34D399', highlight: '#6EE7B7', badge: 'bg-emerald-950/80 text-emerald-300 border-emerald-800/80' },\n      decision: { bg: '#D97706', border: '#FBBF24', highlight: '#FDE68A', badge: 'bg-amber-950/80 text-amber-300 border-amber-800/80' },\n      agent: { bg: '#E11D48', border: '#FB7185', highlight: '#FDA4AF', badge: 'bg-rose-950/80 text-rose-300 border-rose-800/80' },\n      system: { bg: '#4F46E5', border: '#818CF8', highlight: '#A5B4FC', badge: 'bg-indigo-950/80 text-indigo-300 border-indigo-800/80' },\n      tool: { bg: '#0D9488', border: '#2DD4BF', highlight: '#5EEAD4', badge: 'bg-teal-950/80 text-teal-300 border-teal-800/80' },\n      default: { bg: '#475569', border: '#94A3B8', highlight: '#CBD5E1', badge: 'bg-slate-800 text-slate-300 border-slate-700' }\n    };\n\n    function getTypeStyle(type) {\n      const key = (type || '').toLowerCase();\n      return TYPE_STYLES[key] || TYPE_STYLES.default;\n    }\n\n    // --- BUILT-IN REALISTIC DEMO DATASET ---\n    const DEMO_DATASET = {\n      entities: [\n        { id: \"e1\", name: \"TokenVault\", type: \"component\", aliases: [\"Vault\", \"KeyVault\"], metadata: { language: \"TypeScript\", file: \"src/crypto/vault.ts\" } },\n        { id: \"e2\", name: \"AES-256-GCM\", type: \"technology\", aliases: [\"AES-GCM\", \"AES256\"], metadata: { standard: \"NIST SP 800-38D\", key_bits: 256 } },\n        { id: \"e3\", name: \"PBKDF2\", type: \"technology\", aliases: [\"KeyDerivation\"], metadata: { rounds: 100000, hash: \"SHA-256\" } },\n        { id: \"e4\", name: \"OAuth\", type: \"concept\", aliases: [\"OAuth2\"], metadata: { rfc: \"RFC 6749\" } },\n        { id: \"e5\", name: \"Supabase Edge Functions\", type: \"system\", aliases: [\"Edge Runtime\", \"Deno Edge\"], metadata: { provider: \"Supabase\" } },\n        { id: \"e6\", name: \"pgvector\", type: \"technology\", aliases: [\"vector\", \"embeddings-store\"], metadata: { index: \"HNSW\", metric: \"cosine\" } },\n        { id: \"e7\", name: \"Google Gemini Embeddings\", type: \"system\", aliases: [\"gemini-embedding-001\"], metadata: { dimensions: 768, freeTier: true } },\n        { id: \"e8\", name: \"Mnesia Memory Server\", type: \"component\", aliases: [\"Mnesia\", \"MnesiaMemorySystem\"], metadata: { protocol: \"MCP\", version: \"1.1.0\" } },\n        { id: \"e9\", name: \"Antigravity Coordinator\", type: \"agent\", aliases: [\"Coordinator\", \"AGY\"], metadata: { role: \"fleet-lead\" } },\n        { id: \"e10\", name: \"Coder Agent\", type: \"agent\", aliases: [\"coder_agent\"], metadata: { role: \"implementation\" } },\n        { id: \"e11\", name: \"Quota-Aware SHA-256 Cache\", type: \"decision\", aliases: [\"HashCache\"], metadata: { status: \"implemented\", savings: \"100% on duplicate texts\" } },\n        { id: \"e12\", name: \"DES Encryption\", type: \"technology\", aliases: [\"DES\"], metadata: { deprecated: true } },\n      ],\n      relations: [\n        { id: \"r1\", src: \"e1\", dst: \"e2\", predicate: \"uses\", valid_from: \"2026-11-15T12:00:00Z\", valid_to: null, memory_id: \"m1\" },\n        { id: \"r2\", src: \"e1\", dst: \"e3\", predicate: \"uses\", valid_from: \"2026-11-15T12:00:00Z\", valid_to: null, memory_id: \"m1\" },\n        { id: \"r3\", src: \"e1\", dst: \"e4\", predicate: \"protects\", valid_from: \"2026-11-15T12:00:00Z\", valid_to: null, memory_id: \"m1\" },\n        { id: \"r4\", src: \"e8\", dst: \"e5\", predicate: \"runs_on\", valid_from: \"2026-11-15T14:00:00Z\", valid_to: null, memory_id: \"m2\" },\n        { id: \"r5\", src: \"e8\", dst: \"e6\", predicate: \"stores_in\", valid_from: \"2026-11-15T14:00:00Z\", valid_to: null, memory_id: \"m2\" },\n        { id: \"r6\", src: \"e8\", dst: \"e7\", predicate: \"queries\", valid_from: \"2026-11-15T14:00:00Z\", valid_to: null, memory_id: \"m2\" },\n        { id: \"r7\", src: \"e8\", dst: \"e11\", predicate: \"implements\", valid_from: \"2026-11-16T10:00:00Z\", valid_to: null, memory_id: \"m3\" },\n        { id: \"r8\", src: \"e9\", dst: \"e8\", predicate: \"coordinates_via\", valid_from: \"2026-11-16T11:00:00Z\", valid_to: null, memory_id: \"m4\" },\n        { id: \"r9\", src: \"e10\", dst: \"e8\", predicate: \"queries\", valid_from: \"2026-11-16T11:00:00Z\", valid_to: null, memory_id: \"m4\" },\n        { id: \"r10\", src: \"e10\", dst: \"e1\", predicate: \"implements\", valid_from: \"2026-11-16T12:00:00Z\", valid_to: null, memory_id: \"m1\" },\n        // Superseded historical relation demonstrating temporal validity\n        { id: \"r11\", src: \"e1\", dst: \"e12\", predicate: \"uses\", valid_from: \"2026-11-14T09:00:00Z\", valid_to: \"2026-11-15T12:00:00Z\", memory_id: \"m5\" }\n      ],\n      memories: [\n        {\n          id: \"m1\",\n          agent_id: \"coder_agent\",\n          session_id: \"session_sec_audit\",\n          category: \"decision\",\n          content: \"TokenVault requires AES-256-GCM encryption with PBKDF2 key derivation for OAuth tokens to satisfy security compliance.\",\n          tags: [\"security\", \"oauth\", \"crypto\", \"tokenvault\"],\n          created_at: \"2026-11-15T12:00:00Z\",\n          metadata: { ticket: \"SEC-104\", verified: true }\n        },\n        {\n          id: \"m2\",\n          agent_id: \"antigravity_lead\",\n          session_id: \"arch_review\",\n          category: \"fact\",\n          content: \"Mnesia Edge memory server deployed onto Supabase Edge Runtime (Deno), connecting to pgvector with HNSW index and Gemini 768-dim embeddings.\",\n          tags: [\"architecture\", \"supabase\", \"pgvector\", \"gemini\"],\n          created_at: \"2026-11-15T14:00:00Z\",\n          metadata: { env: \"production\", latency_p95: \"85ms\" }\n        },\n        {\n          id: \"m3\",\n          agent_id: \"coder_agent\",\n          session_id: \"perf_optimization\",\n          category: \"decision\",\n          content: \"Added SHA-256 content deduplication cache to store_memory to prevent duplicate embedding API calls and conserve Gemini rate quotas.\",\n          tags: [\"performance\", \"caching\", \"gemini\", \"quota\"],\n          created_at: \"2026-11-16T10:00:00Z\",\n          metadata: { savings_pct: 100 }\n        },\n        {\n          id: \"m4\",\n          agent_id: \"antigravity_lead\",\n          session_id: \"fleet_coordination\",\n          category: \"instruction\",\n          content: \"All autonomous agents must invoke recall_shared_memories before inspecting files to avoid redundant investigation and token waste.\",\n          tags: [\"fleet\", \"guidelines\", \"coordination\"],\n          created_at: \"2026-11-16T11:00:00Z\",\n          metadata: { mandatory: true }\n        },\n        {\n          id: \"m5\",\n          agent_id: \"legacy_system\",\n          session_id: \"legacy_v1\",\n          category: \"summary\",\n          content: \"Legacy Vault initially used basic DES cipher before being completely superseded by AES-256-GCM.\",\n          tags: [\"legacy\", \"deprecation\"],\n          created_at: \"2026-11-14T09:00:00Z\",\n          metadata: { status: \"deprecated\" }\n        }\n      ],\n      memory_entities: [\n        { memory_id: \"m1\", entity_id: \"e1\" },\n        { memory_id: \"m1\", entity_id: \"e2\" },\n        { memory_id: \"m1\", entity_id: \"e3\" },\n        { memory_id: \"m1\", entity_id: \"e4\" },\n        { memory_id: \"m2\", entity_id: \"e5\" },\n        { memory_id: \"m2\", entity_id: \"e6\" },\n        { memory_id: \"m2\", entity_id: \"e7\" },\n        { memory_id: \"m2\", entity_id: \"e8\" },\n        { memory_id: \"m3\", entity_id: \"e8\" },\n        { memory_id: \"m3\", entity_id: \"e11\" },\n        { memory_id: \"m4\", entity_id: \"e8\" },\n        { memory_id: \"m4\", entity_id: \"e9\" },\n        { memory_id: \"m4\", entity_id: \"e10\" },\n        { memory_id: \"m5\", entity_id: \"e1\" },\n        { memory_id: \"m5\", entity_id: \"e12\" }\n      ]\n    };\n\n    // --- INITIALIZATION ---\n    window.addEventListener('DOMContentLoaded', () => {\n      lucide.createIcons();\n      initNetwork();\n      loadStoredCredentials();\n      autoConnectOrDemo();\n    });\n\n    function loadStoredCredentials() {\n      // Check URL parameters first (e.g. ?supabaseUrl=...&supabaseKey=...)\n      const urlParams = new URLSearchParams(window.location.search);\n      const urlParam = urlParams.get('supabaseUrl') || urlParams.get('url');\n      const keyParam = urlParams.get('supabaseKey') || urlParams.get('key') || urlParams.get('apikey');\n\n      const savedUrl = urlParam || localStorage.getItem('mnesia_supabase_url') || (window.__DEFAULT_SUPABASE_URL__ || '');\n      const savedKey = keyParam || localStorage.getItem('mnesia_supabase_key') || (window.__DEFAULT_SUPABASE_KEY__ || '');\n\n      document.getElementById('cfgSupabaseUrl').value = savedUrl;\n      document.getElementById('cfgSupabaseKey').value = savedKey;\n    }\n\n    async function autoConnectOrDemo() {\n      // 1. Check local proxy tool (/api/graph) first!\n      try {\n        const proxyRes = await fetch('/api/graph');\n        if (proxyRes.ok) {\n          const graphJson = await proxyRes.json();\n          if (graphJson && graphJson.entities) {\n            applyGraphJson(graphJson, 'Live Edge Proxy');\n            return;\n          }\n        }\n      } catch (_) {\n        // Proxy not running\n      }\n\n      // 2. Try configured credentials\n      const url = document.getElementById('cfgSupabaseUrl').value.trim();\n      const key = document.getElementById('cfgSupabaseKey').value.trim();\n\n      if (url && key) {\n        try {\n          await fetchFromSupabase(url, key);\n          return;\n        } catch (e) {\n          console.warn(\"Auto-connect failed, falling back to demo dataset:\", e);\n        }\n      }\n      loadDemoDataset();\n    }\n\n    function applyGraphJson(graphJson, sourceLabel = 'Live Proxy') {\n      rawEntities = graphJson.entities || [];\n      rawRelations = graphJson.relations || [];\n      rawMemories = graphJson.memories || [];\n      rawMemoryEntities = graphJson.memory_entities || [];\n\n      updateStatusBadge('connected', sourceLabel);\n      closeSettingsModal();\n      renderGraph();\n      setTimeout(fitGraph, 300);\n    }\n\n    // --- VIS NETWORK SETUP ---\n    function initNetwork() {\n      const container = document.getElementById('graphContainer');\n      const data = { nodes: new vis.DataSet([]), edges: new vis.DataSet([]) };\n\n      const options = {\n        nodes: {\n          shape: 'dot',\n          size: 20,\n          font: {\n            size: 12,\n            color: '#F8FAFC',\n            face: 'Inter, system-ui, sans-serif',\n            strokeWidth: 3,\n            strokeColor: '#090d16'\n          },\n          borderWidth: 2,\n          shadow: {\n            enabled: true,\n            color: 'rgba(0,0,0,0.6)',\n            size: 8,\n            x: 2,\n            y: 4\n          }\n        },\n        edges: {\n          arrows: {\n            to: { enabled: true, scaleFactor: 0.8 }\n          },\n          font: {\n            size: 11,\n            color: '#94A3B8',\n            strokeWidth: 3,\n            strokeColor: '#090d16',\n            align: 'middle'\n          },\n          color: {\n            color: '#475569',\n            highlight: '#38BDF8',\n            hover: '#64748B'\n          },\n          smooth: {\n            enabled: true,\n            type: 'cubicBezier',\n            roundness: 0.2\n          }\n        },\n        physics: {\n          enabled: isPhysicsActive,\n          solver: 'forceAtlas2Based',\n          forceAtlas2Based: {\n            gravitationalConstant: -60,\n            centralGravity: 0.012,\n            springLength: 120,\n            springConstant: 0.08,\n            damping: 0.45,\n            avoidOverlap: 0.7\n          },\n          stabilization: {\n            iterations: 120,\n            updateInterval: 25\n          }\n        },\n        interaction: {\n          hover: true,\n          tooltipDelay: 120,\n          hideEdgesOnDrag: false,\n          multiselect: false,\n          navigationButtons: true,\n          keyboard: false\n        }\n      };\n\n      network = new vis.Network(container, data, options);\n\n      // Event Listeners\n      network.on('click', onGraphClick);\n      network.on('doubleClick', onGraphDoubleClick);\n      network.on('hoverNode', () => { container.style.cursor = 'pointer'; });\n      network.on('blurNode', () => { container.style.cursor = 'default'; });\n    }\n\n    // --- DATA RENDERING & FILTERING ---\n    function renderGraph() {\n      if (!network) return;\n\n      // 1. Determine active entity set based on Hop Focus Mode\n      let allowedEntityIds = null;\n      if (focusCenterEntityId) {\n        allowedEntityIds = computeHopNeighborhood(focusCenterEntityId, focusHopDepth || 1);\n        document.getElementById('focusModeBox').classList.remove('hidden');\n        const center = rawEntities.find(e => e.id === focusCenterEntityId);\n        document.getElementById('focusEntityName').textContent = center ? center.name : focusCenterEntityId;\n      } else {\n        document.getElementById('focusModeBox').classList.add('hidden');\n      }\n\n      // 2. Filter Entities by type & hop\n      const filteredEntities = rawEntities.filter(ent => {\n        if (allowedEntityIds && !allowedEntityIds.has(ent.id)) return false;\n        if (activeTypeFilters.size > 0 && !activeTypeFilters.has(ent.type?.toLowerCase())) return false;\n        return true;\n      });\n\n      const visibleEntityIds = new Set(filteredEntities.map(e => e.id));\n\n      // 3. Filter Relations\n      let supersededCount = 0;\n      const filteredRelations = rawRelations.filter(rel => {\n        const isSuperseded = Boolean(rel.valid_to);\n        if (isSuperseded) supersededCount++;\n\n        if (!showSuperseded && isSuperseded) return false;\n        // Edge endpoints must be visible\n        if (!visibleEntityIds.has(rel.src) || !visibleEntityIds.has(rel.dst)) return false;\n        return true;\n      });\n\n      document.getElementById('supersededCountPill').textContent = supersededCount;\n\n      // 4. Build vis.DataSet items\n      const nodeItems = filteredEntities.map(ent => {\n        const style = getTypeStyle(ent.type);\n        const aliases = (ent.aliases && ent.aliases.length > 0) ? `\\nAliases: ${ent.aliases.join(', ')}` : '';\n        return {\n          id: ent.id,\n          label: ent.name,\n          title: `[${ent.type?.toUpperCase() || 'CONCEPT'}] ${ent.name}${aliases}`,\n          color: {\n            background: style.bg,\n            border: style.border,\n            highlight: {\n              background: style.highlight,\n              border: '#FFFFFF'\n            }\n          }\n        };\n      });\n\n      const edgeItems = filteredRelations.map(rel => {\n        const isSuperseded = Boolean(rel.valid_to);\n        return {\n          id: rel.id,\n          from: rel.src,\n          to: rel.dst,\n          label: rel.predicate,\n          dashes: isSuperseded ? [5, 5] : false,\n          color: {\n            color: isSuperseded ? '#EF4444' : '#64748B',\n            highlight: isSuperseded ? '#F87171' : '#38BDF8',\n            opacity: isSuperseded ? 0.45 : 0.9\n          },\n          font: {\n            color: isSuperseded ? '#FCA5A5' : '#94A3B8',\n            strokeColor: '#090d16',\n            strokeWidth: 3\n          },\n          title: `Predicate: ${rel.predicate}\\nFrom: ${rel.valid_from || 'unknown'}${rel.valid_to ? `\\nSuperseded: ${rel.valid_to}` : ' (Active)'}`\n        };\n      });\n\n      // Update vis dataset\n      network.setData({\n        nodes: new vis.DataSet(nodeItems),\n        edges: new vis.DataSet(edgeItems)\n      });\n\n      // Update Header Stats\n      document.getElementById('statEntities').textContent = rawEntities.length;\n      document.getElementById('statRelations').textContent = rawRelations.filter(r => !r.valid_to).length;\n      document.getElementById('statMemories').textContent = rawMemories.length;\n\n      renderFilterPills();\n    }\n\n    function computeHopNeighborhood(centerId, maxHops = 1) {\n      const visited = new Set([centerId]);\n      let currentBorder = new Set([centerId]);\n\n      for (let hop = 0; hop < maxHops; hop++) {\n        const nextBorder = new Set();\n        for (const rel of rawRelations) {\n          if (!showSuperseded && rel.valid_to) continue;\n\n          if (currentBorder.has(rel.src) && !visited.has(rel.dst)) {\n            visited.add(rel.dst);\n            nextBorder.add(rel.dst);\n          }\n          if (currentBorder.has(rel.dst) && !visited.has(rel.src)) {\n            visited.add(rel.src);\n            nextBorder.add(rel.src);\n          }\n        }\n        currentBorder = nextBorder;\n        if (currentBorder.size === 0) break;\n      }\n      return visited;\n    }\n\n    function renderFilterPills() {\n      const container = document.getElementById('typeFilterPills');\n      container.innerHTML = '';\n\n      const counts = {};\n      rawEntities.forEach(e => {\n        const t = (e.type || 'concept').toLowerCase();\n        counts[t] = (counts[t] || 0) + 1;\n      });\n\n      Object.entries(counts).forEach(([type, count]) => {\n        const style = getTypeStyle(type);\n        const isActive = activeTypeFilters.size === 0 || activeTypeFilters.has(type);\n        \n        const pill = document.createElement('button');\n        pill.className = `px-2 py-0.5 rounded-full text-[10px] font-medium border transition flex items-center gap-1.5 ${\n          isActive \n            ? `${style.badge} ring-1 ring-white/20` \n            : 'bg-dark-800 text-slate-500 border-slate-700/60 opacity-60'\n        }`;\n        \n        pill.innerHTML = `\n          <span class=\"w-1.5 h-1.5 rounded-full\" style=\"background-color: ${style.bg}\"></span>\n          <span>${type}</span>\n          <span class=\"opacity-70 font-mono\">(${count})</span>\n        `;\n\n        pill.onclick = () => {\n          if (activeTypeFilters.has(type)) {\n            activeTypeFilters.delete(type);\n          } else {\n            activeTypeFilters.add(type);\n          }\n          renderGraph();\n        };\n\n        container.appendChild(pill);\n      });\n    }\n\n    function resetFilters() {\n      activeTypeFilters.clear();\n      showSuperseded = false;\n      document.getElementById('chkShowSuperseded').checked = false;\n      focusCenterEntityId = null;\n      renderGraph();\n      fitGraph();\n    }\n\n    function toggleSuperseded(checked) {\n      showSuperseded = checked;\n      renderGraph();\n    }\n\n    // --- GRAPH CLICK & SELECTION ---\n    function onGraphClick(params) {\n      if (params.nodes && params.nodes.length > 0) {\n        const nodeId = params.nodes[0];\n        inspectEntity(nodeId);\n      } else if (params.edges && params.edges.length > 0) {\n        const edgeId = params.edges[0];\n        inspectRelation(edgeId);\n      } else {\n        closeInspector();\n      }\n    }\n\n    function onGraphDoubleClick(params) {\n      if (params.nodes && params.nodes.length > 0) {\n        const nodeId = params.nodes[0];\n        // Focus neighborhood 1-hop\n        focusCenterEntityId = (focusCenterEntityId === nodeId) ? null : nodeId;\n        focusHopDepth = 1;\n        renderGraph();\n        network.focus(nodeId, { scale: 1.2, animation: { duration: 500, easingFunction: 'easeInOutQuad' } });\n      }\n    }\n\n    function clearFocusMode() {\n      focusCenterEntityId = null;\n      renderGraph();\n      fitGraph();\n    }\n\n    // --- INSPECTOR DRAWER ---\n    function inspectEntity(entityId) {\n      selectedEntityId = entityId;\n      const entity = rawEntities.find(e => e.id === entityId);\n      if (!entity) return;\n\n      const style = getTypeStyle(entity.type);\n      const drawer = document.getElementById('inspectorDrawer');\n      const title = document.getElementById('inspectorTitle');\n      const icon = document.getElementById('inspectorIcon');\n      const content = document.getElementById('inspectorContent');\n\n      title.textContent = entity.name;\n      drawer.classList.remove('translate-x-full');\n\n      // Relations\n      const outRels = rawRelations.filter(r => r.src === entityId);\n      const inRels = rawRelations.filter(r => r.dst === entityId);\n\n      // Grounded Memories\n      const groundedMemIds = new Set(\n        rawMemoryEntities.filter(me => me.entity_id === entityId).map(me => me.memory_id)\n      );\n      // Also include memories where relation was evidenced\n      outRels.concat(inRels).forEach(r => { if (r.memory_id) groundedMemIds.add(r.memory_id); });\n      const memories = rawMemories.filter(m => groundedMemIds.has(m.id));\n\n      let aliasesHtml = '';\n      if (entity.aliases && entity.aliases.length > 0) {\n        aliasesHtml = `\n          <div class=\"mt-2 flex flex-wrap gap-1\">\n            ${entity.aliases.map(a => `<span class=\"px-2 py-0.5 rounded bg-dark-800 text-slate-300 border border-slate-700 font-mono text-[10px]\">${escapeHtml(a)}</span>`).join('')}\n          </div>\n        `;\n      }\n\n      let metadataHtml = '';\n      if (entity.metadata && Object.keys(entity.metadata).length > 0) {\n        metadataHtml = `\n          <div class=\"space-y-1\">\n            <span class=\"text-[11px] font-semibold text-slate-400 uppercase tracking-wider\">Metadata</span>\n            <pre class=\"p-2.5 rounded-lg bg-dark-950 border border-slate-800 font-mono text-[11px] text-slate-300 overflow-x-auto\">${escapeHtml(JSON.stringify(entity.metadata, null, 2))}</pre>\n          </div>\n        `;\n      }\n\n      // Outbound Relations List\n      let outRelsHtml = outRels.length === 0 ? '<div class=\"text-slate-500 italic text-[11px]\">None</div>' : outRels.map(r => {\n        const target = rawEntities.find(e => e.id === r.dst);\n        const isSup = Boolean(r.valid_to);\n        return `\n          <div class=\"p-2 rounded-lg bg-dark-800/80 border border-slate-700/60 flex items-center justify-between\">\n            <div class=\"flex items-center gap-1.5 overflow-hidden\">\n              <span class=\"font-mono text-emerald-400 font-medium\">${escapeHtml(r.predicate)}</span>\n              <span class=\"text-slate-500\">→</span>\n              <button onclick=\"focusAndInspectNode('${r.dst}')\" class=\"text-white hover:text-emerald-300 font-medium truncate underline underline-offset-2\">\n                ${escapeHtml(target ? target.name : r.dst)}\n              </button>\n            </div>\n            ${isSup ? '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-red-950/80 text-red-400 border border-red-800\">superseded</span>' : '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-emerald-950/80 text-emerald-400 border border-emerald-800\">active</span>'}\n          </div>\n        `;\n      }).join('');\n\n      // Inbound Relations List\n      let inRelsHtml = inRels.length === 0 ? '<div class=\"text-slate-500 italic text-[11px]\">None</div>' : inRels.map(r => {\n        const source = rawEntities.find(e => e.id === r.src);\n        const isSup = Boolean(r.valid_to);\n        return `\n          <div class=\"p-2 rounded-lg bg-dark-800/80 border border-slate-700/60 flex items-center justify-between\">\n            <div class=\"flex items-center gap-1.5 overflow-hidden\">\n              <button onclick=\"focusAndInspectNode('${r.src}')\" class=\"text-white hover:text-emerald-300 font-medium truncate underline underline-offset-2\">\n                ${escapeHtml(source ? source.name : r.src)}\n              </button>\n              <span class=\"text-slate-500\">→</span>\n              <span class=\"font-mono text-sky-400 font-medium\">${escapeHtml(r.predicate)}</span>\n            </div>\n            ${isSup ? '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-red-950/80 text-red-400 border border-red-800\">superseded</span>' : '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-emerald-950/80 text-emerald-400 border border-emerald-800\">active</span>'}\n          </div>\n        `;\n      }).join('');\n\n      // Memories HTML\n      let memoriesHtml = memories.length === 0 ? '<div class=\"text-slate-500 italic text-[11px]\">No grounded memories</div>' : memories.map(m => `\n        <div class=\"p-3.5 rounded-lg bg-dark-800 border border-slate-700/80 space-y-2.5\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"px-2 py-0.5 rounded-full text-[10px] bg-purple-950 text-purple-300 border border-purple-800 font-medium\">${escapeHtml(m.category || 'general')}</span>\n            <span class=\"text-[10px] text-slate-500 font-mono\">${formatDate(m.created_at)}</span>\n          </div>\n          <div class=\"prose-dark\">\n            ${renderMarkdown(m.content)}\n          </div>\n          <div class=\"flex items-center justify-between pt-1.5 border-t border-slate-700/40 text-[10px] text-slate-400\">\n            <span class=\"font-mono text-slate-400\">👤 ${escapeHtml(m.agent_id || 'system')}</span>\n            <div class=\"flex gap-1 flex-wrap\">\n              ${(m.tags || []).map(t => `<span class=\"text-slate-400 font-mono\">#${escapeHtml(t)}</span>`).join(' ')}\n            </div>\n          </div>\n        </div>\n      `).join('');\n\n      const entityDesc = entity.metadata?.description || entity.metadata?.summary || entity.metadata?.notes;\n      const descHtml = entityDesc ? `\n        <div class=\"p-3.5 rounded-xl bg-dark-800/80 border border-slate-700/80 space-y-1.5\">\n          <span class=\"text-[10px] font-semibold text-slate-400 uppercase tracking-wider\">Description</span>\n          <div class=\"prose-dark\">\n            ${renderMarkdown(entityDesc)}\n          </div>\n        </div>\n      ` : '';\n\n      content.innerHTML = `\n        <!-- Entity Badge & Aliases -->\n        <div class=\"p-3 rounded-xl bg-dark-800/80 border border-slate-700/80\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-[10px] font-semibold text-slate-400 uppercase tracking-wider\">Entity Type</span>\n            <span class=\"px-2.5 py-0.5 rounded-full text-[11px] font-semibold ${style.badge}\">\n              ${escapeHtml(entity.type || 'concept')}\n            </span>\n          </div>\n          ${aliasesHtml}\n          <div class=\"mt-3 pt-2 border-t border-slate-700/50 flex justify-between text-[11px] text-slate-400\">\n            <div>Degree: <span class=\"text-white font-mono font-bold\">${outRels.length + inRels.length}</span></div>\n            <div>Grounded Memories: <span class=\"text-purple-400 font-mono font-bold\">${memories.length}</span></div>\n          </div>\n        </div>\n\n        ${descHtml}\n\n        <!-- Quick Neighborhood Action -->\n        <div class=\"flex gap-2\">\n          <button onclick=\"isolateEntityNeighborhood('${entity.id}')\" class=\"flex-1 py-1.5 px-3 bg-dark-800 hover:bg-dark-700 border border-slate-700 rounded-lg text-emerald-400 hover:text-emerald-300 font-medium transition text-center flex items-center justify-center gap-1.5\">\n            <i data-lucide=\"crosshair\" class=\"w-3.5 h-3.5\"></i> Focus 1-Hop\n          </button>\n        </div>\n\n        ${metadataHtml}\n\n        <!-- Outgoing Relations -->\n        <div class=\"space-y-2\">\n          <span class=\"text-[11px] font-semibold text-slate-400 uppercase tracking-wider flex items-center justify-between\">\n            <span>Outgoing Relations</span>\n            <span class=\"text-slate-500 font-mono\">(${outRels.length})</span>\n          </span>\n          <div class=\"space-y-1.5 max-h-48 overflow-y-auto pr-1\">\n            ${outRelsHtml}\n          </div>\n        </div>\n\n        <!-- Incoming Relations -->\n        <div class=\"space-y-2\">\n          <span class=\"text-[11px] font-semibold text-slate-400 uppercase tracking-wider flex items-center justify-between\">\n            <span>Incoming Relations</span>\n            <span class=\"text-slate-500 font-mono\">(${inRels.length})</span>\n          </span>\n          <div class=\"space-y-1.5 max-h-48 overflow-y-auto pr-1\">\n            ${inRelsHtml}\n          </div>\n        </div>\n\n        <!-- Grounded Memories -->\n        <div class=\"space-y-2 pt-2 border-t border-slate-800\">\n          <span class=\"text-[11px] font-semibold text-slate-400 uppercase tracking-wider flex items-center justify-between\">\n            <span>Grounded Memories</span>\n            <span class=\"text-slate-500 font-mono\">(${memories.length})</span>\n          </span>\n          <div class=\"space-y-2 max-h-72 overflow-y-auto pr-1\">\n            ${memoriesHtml}\n          </div>\n        </div>\n      `;\n\n      lucide.createIcons();\n    }\n\n    function inspectRelation(edgeId) {\n      const rel = rawRelations.find(r => r.id === edgeId);\n      if (!rel) return;\n\n      const src = rawEntities.find(e => e.id === rel.src);\n      const dst = rawEntities.find(e => e.id === rel.dst);\n      const isSup = Boolean(rel.valid_to);\n      const evidenceMem = rawMemories.find(m => m.id === rel.memory_id);\n\n      const drawer = document.getElementById('inspectorDrawer');\n      const title = document.getElementById('inspectorTitle');\n      const content = document.getElementById('inspectorContent');\n\n      title.textContent = `Relation: ${rel.predicate}`;\n      drawer.classList.remove('translate-x-full');\n\n      content.innerHTML = `\n        <div class=\"p-3 rounded-xl bg-dark-800/80 border border-slate-700/80 space-y-3\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-[10px] font-semibold text-slate-400 uppercase tracking-wider\">Status</span>\n            ${isSup \n              ? '<span class=\"px-2 py-0.5 rounded-full text-[10px] bg-red-950 text-red-400 border border-red-800 font-medium\">Superseded</span>'\n              : '<span class=\"px-2 py-0.5 rounded-full text-[10px] bg-emerald-950 text-emerald-400 border border-emerald-800 font-medium\">Active</span>'\n            }\n          </div>\n\n          <div class=\"space-y-1.5 font-mono text-xs\">\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-slate-400\">Source:</span>\n              <button onclick=\"focusAndInspectNode('${rel.src}')\" class=\"text-emerald-400 hover:underline font-bold\">${escapeHtml(src ? src.name : rel.src)}</button>\n            </div>\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-slate-400\">Predicate:</span>\n              <span class=\"text-white font-bold\">${escapeHtml(rel.predicate)}</span>\n            </div>\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-slate-400\">Destination:</span>\n              <button onclick=\"focusAndInspectNode('${rel.dst}')\" class=\"text-sky-400 hover:underline font-bold\">${escapeHtml(dst ? dst.name : rel.dst)}</button>\n            </div>\n          </div>\n\n          <div class=\"pt-2 border-t border-slate-700/60 text-[11px] text-slate-400 space-y-1\">\n            <div>Valid From: <span class=\"font-mono text-slate-200\">${formatDate(rel.valid_from)}</span></div>\n            ${rel.valid_to ? `<div>Valid To: <span class=\"font-mono text-red-300\">${formatDate(rel.valid_to)}</span></div>` : ''}\n          </div>\n        </div>\n\n        ${evidenceMem ? `\n          <div class=\"space-y-2\">\n            <span class=\"text-[11px] font-semibold text-slate-400 uppercase tracking-wider\">Grounded Evidence Memory</span>\n            <div class=\"p-3.5 rounded-lg bg-dark-800 border border-slate-700/80 space-y-2.5\">\n              <div class=\"flex items-center justify-between\">\n                <span class=\"px-2 py-0.5 rounded-full text-[10px] bg-purple-950 text-purple-300 border border-purple-800 font-medium\">${escapeHtml(evidenceMem.category)}</span>\n                <span class=\"text-[10px] text-slate-500 font-mono\">${formatDate(evidenceMem.created_at)}</span>\n              </div>\n              <div class=\"prose-dark\">\n                ${renderMarkdown(evidenceMem.content)}\n              </div>\n            </div>\n          </div>\n        ` : ''}\n      `;\n      lucide.createIcons();\n    }\n\n    function closeInspector() {\n      document.getElementById('inspectorDrawer').classList.add('translate-x-full');\n      selectedEntityId = null;\n    }\n\n    function focusAndInspectNode(nodeId) {\n      if (!network) return;\n      network.focus(nodeId, { scale: 1.2, animation: { duration: 500, easingFunction: 'easeInOutQuad' } });\n      inspectEntity(nodeId);\n    }\n\n    function isolateEntityNeighborhood(nodeId) {\n      focusCenterEntityId = nodeId;\n      focusHopDepth = 1;\n      renderGraph();\n      focusAndInspectNode(nodeId);\n    }\n\n    // --- SEARCH & AUTOCOMPLETE ---\n    function handleSearch(val) {\n      const q = val.trim().toLowerCase();\n      const dropdown = document.getElementById('searchDropdown');\n      const btnClear = document.getElementById('btnClearSearch');\n\n      if (!q) {\n        dropdown.classList.add('hidden');\n        btnClear.classList.add('hidden');\n        return;\n      }\n      btnClear.classList.remove('hidden');\n\n      const matches = rawEntities.filter(e => {\n        if (e.name.toLowerCase().includes(q)) return true;\n        if (e.type && e.type.toLowerCase().includes(q)) return true;\n        if (e.aliases && e.aliases.some(a => a.toLowerCase().includes(q))) return true;\n        return false;\n      }).slice(0, 10);\n\n      if (matches.length === 0) {\n        dropdown.innerHTML = '<div class=\"px-3 py-2 text-slate-500 text-xs italic\">No matching entities found</div>';\n        dropdown.classList.remove('hidden');\n        return;\n      }\n\n      dropdown.innerHTML = matches.map(e => {\n        const style = getTypeStyle(e.type);\n        return `\n          <button onclick=\"selectSearchResult('${e.id}')\" class=\"w-full px-3 py-2 text-left hover:bg-dark-700/80 flex items-center justify-between border-b border-slate-700/40 last:border-0 transition\">\n            <div class=\"overflow-hidden\">\n              <div class=\"text-white font-medium text-xs truncate\">${escapeHtml(e.name)}</div>\n              ${e.aliases && e.aliases.length > 0 ? `<div class=\"text-[10px] text-slate-400 truncate\">aka: ${escapeHtml(e.aliases.join(', '))}</div>` : ''}\n            </div>\n            <span class=\"text-[10px] font-semibold px-2 py-0.5 rounded-full ${style.badge}\">${escapeHtml(e.type)}</span>\n          </button>\n        `;\n      }).join('');\n\n      dropdown.classList.remove('hidden');\n    }\n\n    function selectSearchResult(entityId) {\n      document.getElementById('searchDropdown').classList.add('hidden');\n      focusAndInspectNode(entityId);\n    }\n\n    function clearSearch() {\n      document.getElementById('searchInput').value = '';\n      document.getElementById('searchDropdown').classList.add('hidden');\n      document.getElementById('btnClearSearch').classList.add('hidden');\n    }\n\n    // --- TOOLBAR CONTROLS ---\n    function fitGraph() {\n      if (network) network.fit({ animation: { duration: 600, easingFunction: 'easeInOutQuad' } });\n    }\n\n    function togglePhysics() {\n      isPhysicsActive = !isPhysicsActive;\n      network.setOptions({ physics: { enabled: isPhysicsActive } });\n      const btn = document.getElementById('btnPhysicsToggle');\n      if (isPhysicsActive) {\n        btn.classList.add('text-emerald-400');\n        btn.classList.remove('text-slate-400');\n      } else {\n        btn.classList.remove('text-emerald-400');\n        btn.classList.add('text-slate-400');\n      }\n    }\n\n    function toggleLayoutMode() {\n      isHierarchical = !isHierarchical;\n      if (isHierarchical) {\n        network.setOptions({\n          layout: {\n            hierarchical: {\n              enabled: true,\n              direction: 'LR',\n              sortMethod: 'directed',\n              levelSeparation: 150,\n              nodeSpacing: 100\n            }\n          }\n        });\n      } else {\n        network.setOptions({\n          layout: { hierarchical: { enabled: false } },\n          physics: { enabled: isPhysicsActive }\n        });\n      }\n      fitGraph();\n    }\n\n    function exportPNG() {\n      if (!network) return;\n      const canvas = document.querySelector('#graphContainer canvas');\n      if (!canvas) return;\n      const dataURL = canvas.toDataURL('image/png');\n      const a = document.createElement('a');\n      a.href = dataURL;\n      a.download = `mnesia-knowledge-graph-${Date.now()}.png`;\n      a.click();\n    }\n\n    // --- SUPABASE DATA SYNC ---\n    async function fetchFromSupabase(url, key) {\n      updateStatusBadge('connecting', 'Connecting...');\n      \n      const cleanUrl = url.replace(/\\/+$/, '');\n      const headers = {\n        'apikey': key,\n        'Authorization': `Bearer ${key}`,\n        'Content-Type': 'application/json'\n      };\n\n      try {\n        const [entRes, relRes, memRes, memEntRes] = await Promise.all([\n          fetch(`${cleanUrl}/rest/v1/entities?select=*&order=created_at.desc&limit=500`, { headers }),\n          fetch(`${cleanUrl}/rest/v1/relations?select=*&order=created_at.desc&limit=1000`, { headers }),\n          fetch(`${cleanUrl}/rest/v1/memories?select=id,agent_id,session_id,category,content,tags,created_at,metadata&order=created_at.desc&limit=300`, { headers }),\n          fetch(`${cleanUrl}/rest/v1/memory_entities?select=memory_id,entity_id`, { headers }),\n        ]);\n\n        if (!entRes.ok) throw new Error(`Entities query failed: ${entRes.statusText}`);\n        if (!relRes.ok) throw new Error(`Relations query failed: ${relRes.statusText}`);\n\n        rawEntities = await entRes.json();\n        rawRelations = await relRes.json();\n        rawMemories = memRes.ok ? await memRes.json() : [];\n        rawMemoryEntities = memEntRes.ok ? await memEntRes.json() : [];\n\n        // Save to localStorage\n        localStorage.setItem('mnesia_supabase_url', cleanUrl);\n        localStorage.setItem('mnesia_supabase_key', key);\n\n        updateStatusBadge('connected', 'Live Supabase');\n        closeSettingsModal();\n        renderGraph();\n        setTimeout(fitGraph, 300);\n      } catch (err) {\n        console.error(\"Supabase fetch error:\", err);\n        updateStatusBadge('error', 'Sync Failed');\n        throw err;\n      }\n    }\n\n    function loadDemoDataset() {\n      rawEntities = JSON.parse(JSON.stringify(DEMO_DATASET.entities));\n      rawRelations = JSON.parse(JSON.stringify(DEMO_DATASET.relations));\n      rawMemories = JSON.parse(JSON.stringify(DEMO_DATASET.memories));\n      rawMemoryEntities = JSON.parse(JSON.stringify(DEMO_DATASET.memory_entities));\n\n      updateStatusBadge('demo', 'Demo Dataset');\n      closeSettingsModal();\n      renderGraph();\n      setTimeout(fitGraph, 200);\n    }\n\n    async function refreshData() {\n      // 1. Try refreshing via local proxy\n      try {\n        const proxyRes = await fetch('/api/graph?refresh=true');\n        if (proxyRes.ok) {\n          const graphJson = await proxyRes.json();\n          if (graphJson && graphJson.entities) {\n            applyGraphJson(graphJson, 'Live Edge Proxy');\n            return;\n          }\n        }\n      } catch (_) {}\n\n      // 2. Try direct Supabase\n      const url = document.getElementById('cfgSupabaseUrl').value.trim();\n      const key = document.getElementById('cfgSupabaseKey').value.trim();\n      if (url && key) {\n        try {\n          await fetchFromSupabase(url, key);\n        } catch (e) {\n          alert(\"Failed to refresh from Supabase: \" + e.message);\n        }\n      } else {\n        loadDemoDataset();\n      }\n    }\n\n    function updateStatusBadge(state, text) {\n      const indicator = document.getElementById('statusIndicator');\n      const textElem = document.getElementById('statusText');\n      textElem.textContent = text;\n\n      indicator.className = 'w-2 h-2 rounded-full';\n      if (state === 'connected') {\n        indicator.classList.add('bg-emerald-400');\n      } else if (state === 'connecting') {\n        indicator.classList.add('bg-amber-400', 'animate-pulse');\n      } else if (state === 'demo') {\n        indicator.classList.add('bg-sky-400');\n      } else {\n        indicator.classList.add('bg-red-400');\n      }\n    }\n\n    // --- MODAL CONTROLS ---\n    function openSettingsModal() {\n      document.getElementById('settingsModal').classList.remove('hidden');\n      lucide.createIcons();\n    }\n\n    function closeSettingsModal() {\n      document.getElementById('settingsModal').classList.add('hidden');\n    }\n\n    async function saveAndConnectSupabase() {\n      const url = document.getElementById('cfgSupabaseUrl').value.trim();\n      const key = document.getElementById('cfgSupabaseKey').value.trim();\n      const alertBox = document.getElementById('modalStatusAlert');\n\n      if (!url || !key) {\n        alertBox.className = 'p-3 rounded-lg border text-xs bg-red-950/60 text-red-300 border-red-800';\n        alertBox.textContent = 'Please enter both Supabase URL and API Key.';\n        alertBox.classList.remove('hidden');\n        return;\n      }\n\n      alertBox.className = 'p-3 rounded-lg border text-xs bg-amber-950/60 text-amber-300 border-amber-800';\n      alertBox.textContent = 'Connecting to Supabase...';\n      alertBox.classList.remove('hidden');\n\n      try {\n        await fetchFromSupabase(url, key);\n        alertBox.classList.add('hidden');\n      } catch (err) {\n        alertBox.className = 'p-3 rounded-lg border text-xs bg-red-950/60 text-red-300 border-red-800';\n        alertBox.textContent = `Connection error: ${err.message}`;\n        alertBox.classList.remove('hidden');\n      }\n    }\n\n    // --- UTILITIES ---\n    let isDrawerExpanded = false;\n    function toggleDrawerWidth() {\n      const drawer = document.getElementById('inspectorDrawer');\n      const icon = document.getElementById('iconDrawerWidth');\n      isDrawerExpanded = !isDrawerExpanded;\n      if (isDrawerExpanded) {\n        drawer.classList.remove('w-96');\n        drawer.classList.add('w-full', 'md:w-[620px]');\n        icon.setAttribute('data-lucide', 'minimize-2');\n      } else {\n        drawer.classList.remove('w-full', 'md:w-[620px]');\n        drawer.classList.add('w-96');\n        icon.setAttribute('data-lucide', 'maximize-2');\n      }\n      lucide.createIcons();\n    }\n\n    function renderMarkdown(md) {\n      if (!md) return '';\n      if (typeof marked !== 'undefined') {\n        try {\n          return marked.parse(String(md));\n        } catch (e) {\n          console.warn(\"Markdown parse error:\", e);\n        }\n      }\n      return escapeHtml(md).replace(/\\n/g, '<br>');\n    }\n\n    function escapeHtml(str) {\n      if (!str) return '';\n      return String(str)\n        .replace(/&/g, '&amp;')\n        .replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;')\n        .replace(/\"/g, '&quot;')\n        .replace(/'/g, '&#039;');\n    }\n\n    function formatDate(ts) {\n      if (!ts) return '';\n      try {\n        const d = new Date(ts);\n        return d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });\n      } catch (_) {\n        return String(ts);\n      }\n    }\n  </script>\n</body>\n</html>\n";
  return rawHtml.replace("</head>", injectedScript + "\n</head>");
}
